\label{ass:I}
	$ I:X\to (-\infty,+\infty] $ is a functional which can be decomposed as
	\[
	I(x)=\psi(x)+\Phi(x), \quad \forall \ x\in X,
	\]
	where, denoting by $D_{\psi}=\{x\in X: \psi(x)<+\infty\}$ and $D_{\Phi}=\{x\in X: \Phi(x)<+\infty\}$,
	\begin{enumerate}
		\item
		$D_{\Phi}$ is open in $X$ and $D_{I}=D_{\psi}\cap D_{\Phi}\ne\emptyset;$
		\item
		$\psi:X\to\mathbb{R}\cup\{+\infty\} $ is convex and lower semi-continuous;
		moreover, $\psi$ is continuous on any nonempty compact set $A\subset X$ such that $ \sup_{A} \psi $ is finite;
		\item
		$\Phi:X\to\mathbb{R}\cup\{+\infty\} $ is locally Lipschitz continuous in $D_{\Phi}$, i.e. every $x\in D_{\Phi}$ has a neighborhood in which $\Phi$ is Lipschitz continuous;
		\item for any sequence $\{x_n\}$ in $D_{I}$ such that $\operatorname{dist}(x_n, \partial D_{\Phi}) \to 0$, it holds that
		$I(x_n) \to +\infty$.
	\end{enumerate}

\label{def:puntocritico}
	Let $ I : X\to (-\infty,+\infty] $ satisfy Assumption~\ref{ass:I}.
	\begin{enumerate}
		\item
		A point $x \in D_{I}$ is a \emph{critical point} of $I$ if
		\[
		\Phi^{0}(x;z-x) + \psi(z) - \psi(x) \ge 0, \quad \forall \, z \in X,
		\]
where
\[
\Phi^{0}(x;u)\coloneqq\limsup_{w\to x, t\to 0^{+}}\frac{\Phi(w+tu)-\Phi(w)}{t}.
\]
		\item
		A \emph{Palais-Smale} (abbreviated \emph{PS-}) \emph{sequence for $I$ at level $c$}
		is a sequence $\{x_{n}\}$ in $X$ such that $I(x_{n})\to c $ and
		\begin{equation}\label{PS-formula}
		\Phi^{0}(x_{n};z-x_{n})+\psi(z)-\psi(x_{n}) \ge-\epsilon_{n}\|z-x_{n}\|, \quad \forall \, n\in\mathbb{N},\, z\in X,
		\end{equation}
		for some sequence $\epsilon_{n}\to 0^{+}$.
	\end{enumerate}

\label{thm:minmax}
	Let $I=\psi+\Phi$ be a functional satisfying Assumption~\ref{ass:I}
	and the weak Palais-Smale condition at each level $c > \inf I$.
	Moreover, let us assume that there exists $j_0\in \mathbb{N}$ such that
\begin{itemize}
	\item[(i)] $\mathcal{F}_j\neq \emptyset$, for every $j\geq j_0$
	\item[(ii)] $c_j < +\infty$ for every $j \geq j_0$
	\item[(iii)] $c_{j_0} >\inf I$.
\end{itemize}
Then, the functional $I$ has infinitely many critical points. More precisely:
\begin{itemize}
	\item[(a1)] $c_j$ is a critical level of $I$, for every $j\geq j_0$
	\item[(a2)] whenever $c_{j_1} = c_{j_2}$ for some $j_2 > j_1 \geq j_0$, then the functional $I$ has infinitely many critical points at level $c_{j_1}$.
\end{itemize}

\label{teo:main}
Let us assume that $V:  \Omega \to \mathbb{R}$ and $A:\Omega \to 
\mathbb{R}^3$ are of class $C^1$, $T$-periodic in the first variable, and satisfy the following conditions:
\begin{itemize}
	\item[(V)] $V(t,x) < 0$ for every $(t,x) \in \Omega$ and there exist $\kappa > 0$ and $\delta > 0$ such that, for every $i =1,\ldots,N$,
	\begin{equation} \label{eq:Vsing}
	V(t,x) \leq - \frac{\kappa}{\vert x - r_i(t) \vert}, \quad \forall \ (t,x) \in \Omega \mbox{ such that } \vert x - r_i(t) \vert < \delta;
	\end{equation}
	\item[(AV1)] there exists $\kappa' \in (0,1)$ such that
	$$
	\vert A(t,x) \vert \leq -\frac{\kappa'}{c} V(t,x), \quad \forall \ (t,x) \in \Omega;
	$$
	\item[(AV2)] it holds that	
	$$
	\lim_{\vert x \vert \to \infty} \left( |V(t,x)| + \vert \nabla_x V(t,x) + \partial_t A(t,x)\vert +\vert\textnormal{curl}_x A(t,x) \vert \right) = 0,
	$$
	uniformly in $t\in \mathbb{R}$.
\end{itemize}
	Then, equation \eqref{eq:lorentz} has infinitely many $T$-periodic solutions.

\label{pro:compatti}
	For every integer $j \geq 1$, it holds that:
\begin{itemize}
\item[(i)] $\mathcal{F}_j\neq \emptyset$,
\item[(ii)] $c_j < +\infty$.
\end{itemize}

\label{teo:LW}
	In the above setting, let us assume that $q_i<0$, for every $i=1,\ldots,N$. Let
	\begin{equation} \label{eq:defVLW}
	V(t,x)=\sum_{i=1}^{N} V_i(t,x),\quad A(t,x)=\sum_{i=1}^N A_i(t,x),
	\end{equation}
	for every $(t,x)\in \Omega$, where $V_i$ and $A_i$, $i=1,\ldots, N$, are given in \eqref{eq:defvi} and \eqref{eq:defAi}, respectively. 

\noindent
Then, the corresponding Lorentz force equation \eqref{eq:lorentz} has infinitely many $T$-periodic solutions.

\label{teo:MC}
	Let $U:\mathbb{R}\times \mathbb{R}^3\to \mathbb{R}$ be a $C^1$ function, $T$-periodic in the first variable, satisfying $U(t,x) > 0$ for every $(t,x) \in \mathbb{R}\times \mathbb{R}^3$ and
	\begin{equation} \label{eq:ipoU}
	\lim_{|x|\to +\infty} (|U(t,x)|+|\nabla_x U(t,x)|)=0,
	\end{equation}
	uniformly in $t\in \mathbb{R}$.

	\noindent
	Then, equation \eqref{eqkep-fine}
	 has infinitely many $T$-periodic solutions.
